CREATE TABLE IF NOT EXISTS accounts."Attachments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL,
    "EntityType" text NOT NULL,
    "EntityId" integer NOT NULL,
    "Provider" integer NOT NULL DEFAULT 0,
    "Url" text NULL,
    "ExternalId" text NULL,
    "DisplayName" text NOT NULL,
    "MimeType" text NULL,
    "SizeBytes" bigint NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT now(),
    "UpdatedAt" timestamp with time zone NULL,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL
);
CREATE INDEX IF NOT EXISTS "IX_Attachments_Entity" ON accounts."Attachments" ("EntityType", "EntityId");
CREATE INDEX IF NOT EXISTS "IX_Attachments_UserId" ON accounts."Attachments" ("UserId");
